using System;
using System.IO;
using UnityEditor;
internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        if (!EditorApplication.ExecuteMenuItem("Tools/VividRP/Diagnostics/Validate VSM Profiling GC"))
            throw new Exception("Import VSMProfilingGCProbe.cs into the normal Editor assembly after active captures finish.");
        const string path = "Packages/VividRP/Roadmap~/Experiments/VSMCapacityCostDynamic_20260912/profiling-gc-result.txt";
        if (!File.Exists(path)) throw new Exception("Profiling GC menu did not produce a result.");
        string report = File.ReadAllText(path);
        result.Log(report);
        if (!report.TrimEnd().EndsWith("PASS", StringComparison.Ordinal))
            throw new Exception("Profiling GC did not pass; inspect the recorded result.");
    }
}
